// User-defined Literal Suffixes for std::complex (C++14+)

namespace std::literals::complex_literals {}
using namespace std::literals::complex_literals;

// Standard suffixes map literal type to std::complex type

auto z1 = 42.0i;        // Type: std::complex<double>
                        // Real part is 0.0

auto z2 = 1.5if;        // Type: std::complex<float>

auto z3 = 100.0il;      // Type: std::complex<long double>

// Combining real and imaginary components:
auto z4 = 5.0 + 3.0i;   // Type: std::complex<double>

// Suffix structure (e.g., operator""i):
// operator""i(long double val) -> complex<double>
// operator""if(...)           -> complex<float>
// operator""il(...)           -> complex<long double>
